        if n in self.calculated_numbers:
            return self.calculated_numbers[n]

        k = n // 2
        if n % 2 == 0:
            res = (self.fib(k) * self.fib(k) + self.fib(k - 1) * self.fib(k - 1)) % self.mod
        else:
            res = (self.fib(k) * self.fib(k + 1) + self.fib(k - 1) * self.fib(k)) % self.mod

